const products=[{"id": 1, "name": "Fresh & Tender Coconut Selection", "desc": "Fresh tender and mature coconuts selected for quality.", "src": "data:image/jpeg;base64,", "icon": "🥥"}, {"id": 2, "name": "Extra Virgin Coconut Oil", "desc": "Premium coconut oil for everyday use.", "src": "data:image/jpeg;base64,", "icon": "🫙"}, {"id": 3, "name": "Extra Virgin Coconut Cream", "desc": "Rich coconut cream for cooking and recipes.", "src": "data:image/jpeg;base64,", "icon": "🥥"}, {"id": 4, "name": "Coconut Lip Balm", "desc": "Coconut-based lip care for everyday use.", "src": "data:image/jpeg;base64,", "icon": "💧"}, {"id": 5, "name": "Coconut Flour", "desc": "Fine coconut flour for baking and cooking.", "src": "data:image/jpeg;base64,", "icon": "🌾"}, {"id": 6, "name": "Desiccated Coconut", "desc": "Dried coconut prepared for cooking and baking.", "src": "data:image/jpeg;base64,", "icon": "🥥"}, {"id": 7, "name": "Coconut Flakes", "desc": "Coconut flakes for snacks, toppings and recipes.", "src": "data:image/jpeg;base64,", "icon": "🥥"}, {"id": 8, "name": "Coconut Water", "desc": "Refreshing coconut water from fresh coconuts.", "src": "data:image/jpeg;base64,", "icon": "🥤"}, {"id": 9, "name": "Coconut Milk", "desc": "Creamy coconut milk for everyday cooking.", "src": "data:image/jpeg;base64,", "icon": "🥛"}, {"id": 10, "name": "Coconut Sugar", "desc": "Coconut-based sugar for your pantry.", "src": "data:image/jpeg;base64,", "icon": "🍯"}, {"id": 11, "name": "Coconut Aminos", "desc": "Coconut-based seasoning for everyday recipes.", "src": "data:image/jpeg;base64,", "icon": "🍶"}, {"id": 12, "name": "Premium Coconut Essence", "desc": "Coconut essence for baking and food preparation.", "src": "data:image/jpeg;base64,", "icon": "🧴"}, {"id": 13, "name": "Coconut Coir Seed Starter Pots", "desc": "Natural coir starter pots for growing seedlings.", "src": "data:image/jpeg;base64,", "icon": "🌱"}];
let cart=[];
const selectedQty={};
const grid=document.getElementById("productGrid");
grid.innerHTML=products.map(p=>`<article class="product"><div class="product-img"><img src="${p.src}" alt="${p.name}"></div><h3>${p.name}</h3><p>${p.desc}</p><div class="product-actions"><div class="qty-control"><button type="button" onclick="changeQty(${p.id},-1)">−</button><span id="qty-${p.id}">1</span><button type="button" onclick="changeQty(${p.id},1)">+</button></div><button class="add" onclick="addToCart(${p.id})">Add to cart</button></div></article>`).join("");
function changeQty(id,delta){selectedQty[id]=Math.max(1,(selectedQty[id]||1)+delta);document.getElementById("qty-"+id).textContent=selectedQty[id]}
function addToCart(id){const p=products.find(x=>x.id===id);const amount=selectedQty[id]||1;const item=cart.find(x=>x.id===id);if(item)item.qty+=amount;else cart.push({...p,qty:amount});selectedQty[id]=1;document.getElementById("qty-"+id).textContent="1";renderCart();toggleCart(true)}
function renderCart(){document.getElementById("cartCount").textContent=cart.reduce((s,x)=>s+x.qty,0);document.getElementById("cartItems").innerHTML=cart.length?cart.map(x=>`<div class="cart-item"><div><b>${x.name}</b><small>Quantity: ${x.qty}</small></div><strong>Qty ${x.qty}</strong></div>`).join(""):`<p style="color:#6c746b">Your cart is empty.</p>`;document.getElementById("cartTotal").textContent="Price confirmed after order"}
function toggleCart(force){const c=document.getElementById("cart"),o=document.getElementById("overlay");const open=force===true?!c.classList.contains("open"):force===false?false:!c.classList.contains("open");c.classList.toggle("open",open);o.classList.toggle("show",open)}
function checkout(){if(!cart.length){alert("Add a product first.");return}const items=cart.map(x=>`${x.name} × ${x.qty}`).join(", ");const msg=`Hi The Coconut Co., I want to order: ${items}. Please confirm availability, price and delivery across Tamil Nadu.`;window.open("https://wa.me/919940340588?text="+encodeURIComponent(msg),"_blank")}
renderCart();
